SELECT sub.id, sub.detail_id, d.main_id, d.row_no, sub.seq_no, d.so_code, d.platform_order_no, d.track_no, d.transport_no, d.so_delivery_code, d.erp_so_code, d.erp_platform_order_no, d.erp_track_no, d.erp_so_delivery_code, sub.cost_name, sub.cfg_cost_name, sub.actual_amount, sub.currency, d.pay_type, d.weight_logistics, d.volume_weight_logistics, d.billing_weight_logistics, d.weight_unit, d.third_length, d.third_width, d.third_height, d.cost_count, sub.match_status, sub.match_fail_reason, sub.reconciliation_status, d.create_time, d.create_user_name FROM logistics_recon_detail_sub sub INNER JOIN logistics_recon_detail d ON d.id = sub.detail_id AND d.is_deleted = false WHERE ${params.sqlMap.default} and sub.is_deleted = false AND d.main_id = #{params.mainId}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
d.row_no ASC, sub.seq_no ASC

SELECT sub.match_status AS tabFlag, count(*) AS count FROM logistics_recon_detail_sub sub INNER JOIN logistics_recon_detail d ON d.id = sub.detail_id AND d.is_deleted = false WHERE sub.is_deleted = false AND d.main_id = #{params.mainId}
${params.permissionSql}
GROUP BY sub.match_status
